void mptcp_seq_show ( struct seq_file * seq ) { unsigned long sum [ ARRAY_SIZE ( mptcp_snmp_list ) - 1 ] ; struct net * net = seq -> private ; int i ; seq_puts ( seq , "MPTcpExt:" ) ; for ( i = 0 ; mptcp_snmp_list [ i ] . name ; i ++ ) { seq_printf ( seq , " %s" , mptcp_snmp_list [ i ] . name ) ; } seq_puts ( seq , "\nMPTcpExt:" ) ; if ( net -> mib . mptcp_statistics ) { snmp_get_cpu_field_batch ( sum , mptcp_snmp_list , net -> mib . mptcp_statistics ) ; } for ( i = 0 ; mptcp_snmp_list [ i ] . name ; i ++ ) { seq_printf ( seq , " %lu" , sum [ i ] ) ; } seq_putc ( seq , '\n' ) ; } 